// Product app origin. Empty = same origin (the app serves this site at /). Set window.ADCRAFT_APP_URL when hosted apart.
const APP_URL=(window.ADCRAFT_APP_URL||'');
const arrow='<span aria-hidden="true">↗</span>';
const logo='<span class="brand-symbol" aria-hidden="true">✳</span> adcraft<span class="brand-dot">.</span>';
const pathname=location.pathname;const isPricing=pathname.includes('pricing');const isShowcase=pathname.includes('showcase');
const creative=[{id:'glow',title:'A little glow goes a long way.',brand:'ÉCLAT SKIN',type:'Static ads',panel:0,style:'glow',label:'Your daily dose<br>of <em>golden hour.</em>',description:'A warm, product-first concept that lets texture and light do the talking.',hook:'Meet your new morning ritual.',cta:'Find your glow',format:'4:5 · Feed ad'},{id:'routine',title:'The routine worth sharing.',brand:'ÉCLAT SKIN',type:'UGC videos',panel:1,style:'routine',label:'“Okay, I finally get<br>the hype.”',description:'An approachable creator-led concept built around a real-feeling daily routine.',hook:'I changed one thing in my morning routine.',cta:'Meet your everyday essential',format:'9:16 · UGC concept'},{id:'move',title:'Made for your next move.',brand:'STRIDE®',type:'Product videos',panel:2,style:'move',label:'LESS SCROLL.<br>MORE <em>GO.</em>',description:'A bold movement-led direction with vivid color and a single clear message.',hook:'Your next move starts here.',cta:'Make your move',format:'9:16 · Product concept'},{id:'sound',title:'Find your own frequency.',brand:'FORM AUDIO',type:'Static ads',panel:3,style:'sound',label:'Good sound.<br><em>Great escape.</em>',description:'A clean editorial composition that makes one product feel like a whole world.',hook:'A little less noise. A little more you.',cta:'Find your frequency',format:'4:5 · Feed ad'}];
const nav=()=>`<header class="site-header"><a class="brand" href="/" aria-label="Adcraft home">${logo}</a><nav class="desktop-nav" aria-label="Main navigation"><a href="/#possibilities">Platform</a><a ${isShowcase?'aria-current="page"':''} href="/showcase/">Creative showcase</a><a href="/#workflow">How it works</a><a ${isPricing?'aria-current="page"':''} href="/pricing/">Pricing</a></nav><a class="button button-small button-dark header-cta" href="${APP_URL}/sign-in">Open the studio ${arrow}</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button></header>`;
const art=(c,extra='')=>`<div class="ad-art ${c.style} ${extra}" style="--panel:${c.panel*100/3}%"><span class="ad-brand">${c.brand}</span><div class="ad-headline">${c.label}</div><span class="ad-caption">${c.cta} <span>↗</span></span></div>`;
const card=(c)=>`<button class="creative-card" data-creative="${c.id}" aria-label="View ${c.title}">${art(c)}<span class="card-bottom"><span>${c.type}</span><span aria-hidden="true">↗</span></span></button>`;
const footer=()=>`<footer class="site-footer"><div class="footer-top"><div><a class="brand" href="/">${logo}</a><p>A little creative.<br>A lot of possibility.</p></div><div class="footer-links"><div><span>THE PLATFORM</span><a href="/showcase/">Creative studio</a><a href="/#workflow">How it works</a><a href="/pricing/">Pricing</a></div><div><span>MADE FOR YOUR IDEAS</span><a href="/showcase/?format=Static%20ads">Static ads</a><a href="/showcase/?format=UGC%20videos">UGC videos</a><a href="/showcase/?format=Product%20videos">Product videos</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Adcraft</span><span>Showcased brands and ads are illustrative.</span><span>Made for the next big idea. ✳</span></div></footer>`;
const cta=()=>`<section class="final-cta"><div class="eyebrow">THE NEXT ONE COULD BE THE ONE.</div><h2>Less blank canvas.<br><em>More “let’s try this.”</em></h2><a class="button button-dark" href="${APP_URL}/sign-in">Start free with 50 credits ${arrow}</a><span class="cta-spark" aria-hidden="true">✳</span></section>`;
const home=()=>`<main id="main"><section class="hero"><div class="eyebrow"><span class="tiny-star">✳</span> BIG IDEAS. SMALL PRODUCTION TEAM.</div><h1>Your next great ad.<br><em>Just an idea away.</em></h1><p>From “what if” to “that’s the one.” Create beautiful ads,<br class="desktop-break"> find your next winning angle, and keep the ideas coming.</p><div class="hero-actions"><a class="button button-orange" href="${APP_URL}/sign-in">Start free with 50 credits ${arrow}</a><a class="text-button" href="#workflow"><span class="play-small">▶</span> See how it works</a></div><div class="hero-note">Your product. Your brand. A whole new world of possibilities.</div></section>
<section class="creative-wall" aria-label="Sample ad creative"><div class="floating-label"><span>✳</span> A few ideas to get you going</div><div class="wall-grid"><div class="type-ad"><span class="ad-brand">THE CREATIVE<br>POSSIBILITIES</span><p>Same<br>product.<br><em>New<br>energy.</em></p><span class="type-ad-foot">100% your kind of different. ↗</span></div>${creative.map(card).join('')}</div><div class="wall-foot"><span>ONE IDEA. EVERY WAY TO TELL IT.</span><a href="/showcase/">Explore the showcase <span>↗</span></a></div></section>
<section class="platform-strip"><span>MADE FOR THE PLACES<br>YOUR PEOPLE SCROLL.</span><div class="platform-name"><b class="meta-symbol">∞</b> Meta</div><div class="platform-name"><b>◎</b> Instagram</div><div class="platform-name"><b>♪</b> TikTok</div><div class="platform-name google"><b>G</b> Google Ads</div><div class="platform-name"><b class="youtube-icon">▶</b> YouTube</div></section>
<section class="possibilities section-wrap" id="possibilities"><div class="section-head"><div><div class="section-kicker">01 / THE CREATIVE POSSIBILITIES</div><h2>A whole creative team.<br><em>One very good tab.</em></h2></div><p>For the first idea, the fiftieth variation,<br>and everything that happens in between.</p></div><div class="feature-grid"><a class="feature-card feature-orange" href="/showcase/?format=Static%20ads"><div class="feature-top"><span class="line-icon">▧</span><span>↗</span></div><h3>Make them stop.<br>Then make them look.</h3><p>Turn product photos into static ads<br>that feel unmistakably yours.</p><div class="mini-composition"><div class="mini-ad">${art(creative[0])}</div><div class="mini-ad second"><span>Every day.<br><em>A little<br>brighter.</em></span><b>ÉCLAT SKIN</b></div></div><span class="feature-caption">STATIC ADS & CAROUSELS</span></a><a class="feature-card feature-cream" href="/showcase/?format=UGC%20videos"><div class="feature-top"><span class="line-icon">▷</span><span>↗</span></div><h3>A human touch.<br>A fresh perspective.</h3><p>Explore creator-style videos with<br>hooks that start a conversation.</p><div class="ugc-preview">${art(creative[1])}<span class="caption-bubble">your new morning ritual ☀</span><span class="concept-label">UGC CONCEPT</span></div><span class="feature-caption">UGC & PRODUCT VIDEOS</span></a><a class="feature-card feature-green" href="#workflow"><div class="feature-top"><span class="line-icon">⌘</span><span>↗</span></div><h3>Keep the ideas.<br>Lose the busywork.</h3><p>A clearer path from your first brief<br>to your team's favorite creative.</p><div class="workflow-mini"><div><i>✳</i><span>New product brief</span><b>✓</b></div><span class="connector">↓</span><div><i>▧</i><span>Create variations</span><b>✓</b></div><span class="connector">↓</span><div><i>◎</i><span>Ready for review</span><span class="avatars"><b>A</b><b>J</b></span></div></div><span class="feature-caption">WORKFLOWS & COLLABORATION</span></a></div></section>
<section class="workflow-section" id="workflow"><div class="section-wrap workflow-layout"><div class="workflow-copy"><div class="section-kicker">02 / FROM IDEA TO OUT THERE</div><h2>Goodbye, blank page.<br><em>Hello, possibilities.</em></h2><p>A product you believe in.<br>A whole new way to show it to the world.</p><div class="steps" aria-label="Explore the creative process">${[{title:'Bring your starting point.',desc:'One product photo. Endless potential.'},{title:'Find your kind of different.',desc:'Fresh hooks, new angles, your brand.'},{title:'Take your favorites further.',desc:'A little fine-tuning. Ready for every feed.'}].map((st,i)=>`<button class="step ${!i?'active':''}" data-step="${i}" aria-pressed="${!i}"><span class="step-number">0${i+1}</span><span class="step-text"><strong>${st.title}</strong><small>${st.desc}</small></span><span class="step-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div class="workflow-aside"><span>✳</span> One idea is all it takes.</div></div><div class="creative-canvas"><div class="canvas-header"><div class="canvas-project"><span class="project-icon">é</span><div><strong>Éclat Skin</strong><span>Your next creative chapter</span></div></div><span class="canvas-sample">INTERACTIVE PREVIEW</span></div><div class="canvas-progress" aria-label="Preview steps">${['Your product','Your direction','Your creative'].map((label,i)=>`<button data-step="${i}" aria-pressed="${!i}" class="${!i?'active':''}"><span>0${i+1}</span>${label}</button>`).join('')}</div><div class="demo-content" id="demo-content" aria-live="polite"></div><div class="canvas-footer"><span class="canvas-step-count">01 / 03</span><span>Your brand. A fresh perspective.</span><span class="canvas-footer-mark">✳</span></div></div></div></section>
<section class="formats-section section-wrap"><div class="section-kicker">03 / YOUR BRAND, EVERYWHERE</div><div class="section-head"><h2>One brand.<br><em>Never one-note.</em></h2><a class="text-button" href="/showcase/">See what’s possible ${arrow}</a></div><div class="format-row"><span class="format-statement">A fresh angle for<br>every kind of scroll.</span><div><b>9:16</b><span>Stories & Reels</span></div><div><b>1:1</b><span>Feed favorites</span></div><div><b>4:5</b><span>Room to stand out</span></div><div><b>16:9</b><span>The bigger picture</span></div></div></section>${cta()}</main>`;
const showcase=()=>`<main id="main"><section class="page-hero"><div class="eyebrow"><span class="tiny-star">✳</span> THE CREATIVE SHOWCASE</div><h1>A little inspiration.<br><em>A lot of potential.</em></h1><p>Different products. Fresh perspectives. Explore a few directions<br class="desktop-break"> your next campaign could take.</p></section><section class="section-wrap gallery-section"><div class="gallery-toolbar"><div class="filter-tabs" role="group" aria-label="Filter creative format">${['All creative','Static ads','UGC videos','Product videos'].map((v,i)=>`<button data-filter="${v}" class="${!i?'active':''}" aria-pressed="${!i}">${v}</button>`).join('')}</div><span class="gallery-count" aria-live="polite">4 creative concepts</span></div><div class="gallery-grid"></div><div class="gallery-note"><span>✳</span><p>A creative starting point, not a finished campaign.<br>These sample concepts show the look, feel, and storytelling possibilities.</p></div></section>${cta()}</main>`;
const pricing=()=>`<main id="main"><section class="page-hero"><div class="eyebrow"><span class="tiny-star">✳</span> ROOM FOR YOUR NEXT BIG IDEA</div><h1>Small beginnings.<br><em>Big creative energy.</em></h1><p>A plan for your first campaign, your next launch,<br class="desktop-break"> and the team making it all happen.</p><div class="billing-switch" role="group" aria-label="Billing period"><button data-billing="monthly" class="active" aria-pressed="true">Monthly</button><button data-billing="yearly" aria-pressed="false">Yearly <span>Save 20%</span></button></div><p class="pricing-disclaimer">Every workspace starts with 50 free credits. Ad spend is billed by the platforms, never through Adcraft.</p></section><section class="pricing-grid section-wrap">${[{name:'Starter',desc:'For your first “let’s try this.”',price:29,credits:150,items:['1 brand workspace','150 credits a month','Static ads, carousels and product video','UGC video with AI presenter','Every size for Meta, TikTok, Google and YouTube','2 ad accounts']},{name:'Studio',desc:'For brands with more to say.',price:79,credits:500,popular:true,items:['3 brand workspaces','500 credits a month','Everything in Starter','Team review and approvals','Video priority in the queue','5 ad accounts']},{name:'Agency',desc:'For a whole world of brands.',price:199,credits:1500,items:['10 brand workspaces','1,500 credits a month','Everything in Studio','Client review workspaces','Shared templates and brand kits','Priority generation queue']}].map(p=>`<article class="price-card ${p.popular?'popular':''}">${p.popular?'<div class="popular-label">A LITTLE MORE ROOM TO CREATE ✳</div>':''}<span class="plan-name">${p.name}</span><p>${p.desc}</p><div class="plan-price"><span class="price-value" data-price="${p.price}">$${p.price}</span><span>/ month</span></div><span class="billing-detail">Billed monthly</span><a class="button ${p.popular?'button-orange':'button-outline'}" href="${APP_URL}/sign-in">Start with ${p.name} ${arrow}</a><span class="included-label">WHAT’S INCLUDED</span><ul>${p.items.map(x=>`<li><span>✓</span>${x}</li>`).join('')}</ul></article>`).join('')}</section><p class="credit-note">A concept set costs 1 credit, a static ad in every size 2, a 15-second product video 20, and a 30-second UGC video 40. Top up 100 credits for $10 any time. Ad spend is separate.</p><section class="section-wrap compare-section" id="compare"><div class="section-kicker">THE DETAILS, AT A GLANCE</div><h2>Find your <em>creative fit.</em></h2><div class="table-scroll"><table><caption class="sr-only">Planned feature comparison across pricing plans</caption><thead><tr><th>Made for the way you work</th><th>Starter</th><th>Studio</th><th>Agency</th></tr></thead><tbody>${[['Brand workspaces','1','3','10'],['Credits a month','150','500','1,500'],['Static ads, video and UGC','Included','Included','Included'],['Product library with cutouts','Included','Included','Included'],['Connected ad accounts','2','5','Unlimited'],['Review and approvals','—','Team','Team and client'],['Shared templates and brand kits','—','—','Included'],['Priority generation queue','—','Video','Everything']].map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'} ${!i?'scope="row"':''}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="faq-section section-wrap"><div><div class="section-kicker">A FEW GOOD QUESTIONS</div><h2>Glad <em>you asked.</em></h2></div><div class="faqs">${[['Can I subscribe now?','Yes. Every workspace starts with 50 free credits, and you can move to Starter, Studio or Agency from inside the app whenever you need more.'],['How do generation credits work?','A concept set costs 1 credit, a static ad in every size costs 2, a 15-second product video costs 20, and a 30-second UGC video with presenter costs 40. Resizing is free.'],['Does pricing include advertising spend?','No. Creative generation and workspace access are separate from the budgets you spend on Meta, TikTok, Google, or other advertising platforms.'],['Can I use my own product photos and branding?','That is central to the planned experience: your product assets, brand colors, tone, and creative direction in one workspace.'],['Will you publish and manage my campaigns?','Yes. Connect Meta, TikTok and Google Ads accounts, build a campaign in one form, publish paused or live, and see spend, CTR, CPA and ROAS per creative back in Adcraft.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section>${cta()}</main>`;
const demoSteps=[`<div class="canvas-stage-heading"><span class="workspace-label">THE STARTING POINT</span><h3>A little something.<br><em>A world of possibility.</em></h3></div><div class="brief-canvas"><div class="brief-product" role="img" aria-label="Everyday Serum bottle photographed in warm golden light"><span class="photo-badge">YOUR PRODUCT</span><span class="photo-filename">everyday-serum.jpg <b>✓</b></span></div><div class="brief-details"><span class="brief-overline">MEET THE BRAND</span><h4>Golden hour.<br>In a bottle.</h4><p>The Everyday Serum<br><span>Skincare, with a sunny side.</span></p><div class="brand-swatches"><i style="--swatch:#ed9a70"></i><i style="--swatch:#f5d6b4"></i><i style="--swatch:#98694b"></i><span>Éclat palette</span></div><div class="brief-tone"><span>THE FEELING</span><div><b>Warm</b><b>Effortless</b><b>A little playful</b></div></div></div></div><div class="canvas-action"><span><i>✧</i> Let’s see where this can go.</span><button class="button button-dark" data-next="1">Find my direction ${arrow}</button></div>`,`<div class="canvas-stage-heading"><span class="workspace-label">THE CREATIVE DIRECTION</span><h3>Same little bottle.<br><em>Two fresh perspectives.</em></h3></div><div class="direction-grid"><button class="direction-option selected" data-direction="glow" aria-pressed="true"><div class="direction-image">${art(creative[0])}<span class="direction-check">✓</span></div><span class="direction-info"><strong>Your daily golden hour</strong><small>PRODUCT-LED · WARM & MINIMAL</small></span></button><button class="direction-option" data-direction="routine" aria-pressed="false"><div class="direction-image">${art(creative[1])}<span class="direction-check">✓</span></div><span class="direction-info"><strong>The routine worth sharing</strong><small>CREATOR-LED · HONEST & PERSONAL</small></span></button></div><div class="canvas-action"><span><i>✧</i> Pick the story that feels like you.</span><button class="button button-dark" data-next="2">Meet the creative ${arrow}</button></div>`,`<div class="canvas-stage-heading"><span class="workspace-label">THE NEXT CHAPTER</span><h3>One good idea.<br><em>Everywhere it needs to be.</em></h3></div><div class="output-canvas"><button class="output-card output-feed" data-creative="glow" aria-label="View Your daily golden hour feed concept">${art(creative[0])}<span>THE FEED EDIT <b>4:5</b></span></button><button class="output-card output-story" data-creative="routine" aria-label="View The routine worth sharing story concept">${art(creative[1])}<span>THE STORY EDIT <b>9:16</b></span></button><span class="output-sticker">A little more<br><em>you.</em> ✳</span></div><div class="canvas-action"><span><i>✧</i> Your next favorite is in here.</span><a class="button button-dark" href="/showcase/">Explore the showcase ${arrow}</a></div>`];
let chosenDirection='glow';
function render(){document.getElementById('app').innerHTML=nav()+(isPricing?pricing():isShowcase?showcase():home())+footer()+`<dialog class="creative-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="Close concept">×</button><div id="dialog-content"></div></dialog>`;document.querySelector('.menu-toggle').onclick=e=>{let open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);document.querySelector('.desktop-nav').classList.toggle('open',open)};document.querySelectorAll('.desktop-nav a').forEach(a=>a.onclick=()=>{document.querySelector('.desktop-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')});if(isShowcase)setFilter(new URLSearchParams(location.search).get('format')||'All creative');if(!isPricing&&!isShowcase)setStep(0);document.querySelectorAll('[data-billing]').forEach(b=>b.onclick=()=>setBilling(b.dataset.billing));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step));document.querySelector('.dialog-close').onclick=()=>document.querySelector('dialog').close();document.querySelector('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});bindCards();}
function bindCards(){document.querySelectorAll('[data-creative]').forEach(b=>b.onclick=()=>openCreative(b.dataset.creative));document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>setStep(+b.dataset.next));}
function openCreative(id){let c=creative.find(x=>x.id===id);document.getElementById('dialog-content').innerHTML=`<div class="dialog-art">${art(c)}</div><div class="dialog-copy"><div class="section-kicker">${c.type.toUpperCase()} · SAMPLE CONCEPT</div><h2 id="dialog-title">${c.title}</h2><p>${c.description}</p><dl><dt>THE OPENING HOOK</dt><dd>“${c.hook}”</dd><dt>THE CALL TO ACTION</dt><dd>${c.cta}</dd><dt>THE FORMAT</dt><dd>${c.format}</dd></dl><p class="dialog-note">Illustrative creative direction. Video concepts are storyboards, not playable videos.</p><button class="button button-dark close-inside">Keep exploring ${arrow}</button></div>`;document.querySelector('.close-inside').onclick=()=>document.querySelector('dialog').close();document.querySelector('dialog').showModal();}
function setFilter(filter){const valid=['All creative','Static ads','UGC videos','Product videos'];if(!valid.includes(filter))filter='All creative';document.querySelectorAll('[data-filter]').forEach(b=>{let active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});const shown=creative.filter(c=>filter==='All creative'||c.type===filter);document.querySelector('.gallery-grid').innerHTML=shown.map(c=>`<article>${card(c)}<h2>${c.title}</h2><p>${c.brand} <span>·</span> ${c.format}</p></article>`).join('');document.querySelector('.gallery-count').textContent=`${shown.length} creative concept${shown.length===1?'':'s'}`;bindCards();}
function setStep(step){document.querySelectorAll('[data-step]').forEach(b=>{let active=+b.dataset.step===step;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.getElementById('demo-content').innerHTML=demoSteps[step];document.querySelector('.canvas-step-count').textContent=`0${step+1} / 03`;document.querySelectorAll('[data-direction]').forEach(b=>{b.classList.toggle('selected',b.dataset.direction===chosenDirection);b.setAttribute('aria-pressed',b.dataset.direction===chosenDirection);b.onclick=()=>{chosenDirection=b.dataset.direction;document.querySelectorAll('[data-direction]').forEach(o=>{o.classList.toggle('selected',o===b);o.setAttribute('aria-pressed',o===b)})}});if(step===2&&chosenDirection==='routine'){document.querySelector('.output-feed').innerHTML=art(creative[1])+'<span>THE FEED EDIT <b>4:5</b></span>';document.querySelector('.output-feed').dataset.creative='routine';document.querySelector('.output-feed').setAttribute('aria-label','View The routine worth sharing feed concept');document.querySelector('.output-story').innerHTML=art(creative[0])+'<span>THE STORY EDIT <b>9:16</b></span>';document.querySelector('.output-story').dataset.creative='glow';document.querySelector('.output-story').setAttribute('aria-label','View Your daily golden hour story concept')}bindCards();}
function setBilling(period){document.querySelectorAll('[data-billing]').forEach(b=>{let active=b.dataset.billing===period;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.querySelectorAll('[data-price]').forEach(el=>{const amount=+el.dataset.price;el.textContent='$'+(period==='yearly'?(amount*.8).toFixed(2):amount)});document.querySelectorAll('.billing-detail').forEach((el,i)=>{const amount=+document.querySelectorAll('[data-price]')[i].dataset.price;el.textContent=period==='yearly'?`$${(amount*.8*12).toFixed(2)} billed yearly`:'Billed monthly'});}
render();
